effect.shader:
// globais do Node ligados ao motor (tools/nodevideo/ligar_globais.py)
#define _resolution acTamanhoDaTela
vec4 u_xlat0;
vec4 u_xlat1;
float u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
vec2 u_xlat12;
vec2 u_xlat13;
float u_xlat18;
void main()
{
    u_xlat0.xy = vec2(vec2(_scale, _scale)) * vec2(10.0, 5.0);
    u_xlat12.x = _size + -0.5;
    u_xlat12.x = u_xlat12.x * -10.0;
    u_xlat18 = 3.1415925 / u_xlat0.x;
    u_xlat12.x = u_xlat12.x / u_xlat0.x;
    u_xlat1.xy = acScreenNorm.xy + vec2(-0.5, -0.5);
    u_xlat1.xy = u_xlat1.xy * _resolution.xy;
    u_xlat13.xy = vec2(u_xlat18) * u_xlat1.xy;
    u_xlat13.xy = sin(u_xlat13.xy);
    u_xlat12.xy = (-u_xlat12.xx) + abs(u_xlat13.xy);
    u_xlat1.xy = u_xlat1.xy / u_xlat0.xx;
    u_xlat1.xy = floor(u_xlat1.xy);
    u_xlat0.xy = u_xlat1.xy * u_xlat0.xx + u_xlat0.yy;
    u_xlat0.xy = u_xlat0.xy / _resolution.xy;
    u_xlat0.xy = u_xlat0.xy + vec2(0.5, 0.5);
    u_xlat1 = texture(inputImg, u_xlat0.xy);
    u_xlat1 = u_xlat12.xxxx * u_xlat1;
    u_xlat0 = u_xlat12.yyyy * u_xlat1;
    u_xlat1 = texture(inputImg, acScreenNorm.xy);
    u_xlat0 = u_xlat0 * vec4(vec4(_brightness, _brightness, _brightness, _brightness)) + (-u_xlat1);
    u_xlat0 = vec4(vec4(_blend, _blend, _blend, _blend)) * u_xlat0 + u_xlat1;
    if(int(_use_inner_mask) != 0) {
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat0;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat1 = u_xlat1 * u_xlat5;
        u_xlat1 = u_xlat3 * u_xlat4 + u_xlat1;
        u_xlat2 = u_xlat4.x * u_xlat1.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2 : u_xlat1.w;
        fragColor.xyz = u_xlat1.xyz;
    } else {
        fragColor = u_xlat0;
    }
    return;
}
